from ute_ue import ute_ue
from taf.ue.taf_config import collector
from taf.ue.translator import translate_taf_to_ute_ue


class Ue(object):
    """Class contains common keywords for UEs"""
    def __init__(self, ue_config=None):
        """
        Constructor of Ue class.

        Parameters:
        :param ue_config: dict based on test line configuration from __init__.py file. Example of ue_config dictionary:
        {'UE_3': ['REAL_UE', 'REAL_QUALCOMM_UE'],
        'UE_2': ['REAL_UE', 'REAL_ANDROID_UE', 'WITH_PACKET_AND_BUFFER_PARAM'],
        'UE_1': ['REAL_UE', 'REAL_ANDROID_UE', 'WITHOUT_PACKET_AND_BUFFER_PARAM']}
        """

        self.ue = ute_ue()
        self.ue_config = ue_config if ue_config else self.get_default_ue_config()

    def get_default_ue_config(self):
        """
        :param config_path: path to YAML config file
        :return: dictionary consisting of UE IDs and it's capabilities. Example:
        {'UE_3': ['REAL_UE', 'REAL_QUALCOMM_UE'],
        'UE_2': ['REAL_UE', 'REAL_ANDROID_UE', 'WITH_PACKET_AND_BUFFER_PARAM'],
        'UE_1': ['REAL_UE', 'REAL_ANDROID_UE', 'WITHOUT_PACKET_AND_BUFFER_PARAM']}
        """
        taf_config = collector.collect()
        ute_ue_config = translate_taf_to_ute_ue(taf_config)
        ues_config = ute_ue_config["UE_POOLS"]
        ue_config = dict()
        ue_id = 1
        for ue_pool in ues_config:
            for ue_name in ues_config[ue_pool]['inline_config'].keys():
                ue_capabilities = ues_config[ue_pool]['inline_config'][ue_name]['CAPABILITIES']
                ue_config["UE{}".format(ue_id)] = ue_capabilities
                ue_id += 1
        return ue_config

    def require_all_ues(self):
        """
        Connect all UEs defined in configurations.
        :return: None
        """
        for ue_alias in self.ue_config:
            self.ue.require_ue(ue_alias)

    def attach_all_ues(self):
        """
        Attach all UEs defined in configurations.
        :return: None
        """
        for ue_alias in self.ue_config:
            self.ue.attach_ue(ue_alias)

    def detach_all_ues(self):
        """
        Detach all UEs defined in configurations.
        :return: None
        """
        for ue_alias in self.ue_config:
            self.ue.detach_ue(ue_alias)
